import{_ as o,o as t,c as r,ag as d}from"./chunks/framework.BaNuf0sO.js";const h=JSON.parse('{"title":"ImagePreviewTrigger（图片预览触发组件）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/modal/docs/README-ImagePreviewTrigger.md","filePath":"docs/core/src/components/modal/docs/README-ImagePreviewTrigger.md"}'),a={name:"docs/core/src/components/modal/docs/README-ImagePreviewTrigger.md"};function c(i,e,s,l,n,g){return t(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="imagepreviewtrigger-图片预览触发组件" tabindex="-1">ImagePreviewTrigger（图片预览触发组件） <a class="header-anchor" href="#imagepreviewtrigger-图片预览触发组件" aria-label="Permalink to &quot;ImagePreviewTrigger（图片预览触发组件）&quot;">​</a></h1><blockquote><p>图片触发原语：<code>ElImage</code> 落地（img 原生属性对齐）+ 懒加载 + 加载中/失败占位兜底；<strong>点击直接走 ElImage 自带预览（el-image-viewer 放大）</strong>——点图即放大，一层到位，不经弹窗。 与 <code>VideoPreviewTrigger</code> 对等成对（视频触发端仍需弹窗；图片预览终点是 el 原生查看器）。 范式页：<code>apps/reference/src/pages/modal/preview/showcase/</code></p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>何时用</strong>：任意「缩略图可点开看大图」场景——上传文件列表、附件卡片、图片墙</li><li><strong>何时不用</strong>：仅展示不点击 → 直接用 <code>ElImage</code>；命令式开图（按钮/编排，不经过点击）→ <code>ModalImagePreview</code> + 全局遥控器 evoke</li><li>关键机制：落地 <strong><code>ElImage</code></strong>（非裸 <code>&lt;img&gt;</code>）——原生 img 属性照常 <code>$attrs</code> 透传对齐，同时白拿组件库三件套：<strong><code>lazy</code>（默认开）</strong> + <strong><code>#placeholder</code>（加载中占位）</strong> + <strong><code>#error</code>（加载失败兜底图）</strong> + <strong><code>preview-src-list</code>（点击放大）</strong></li><li><strong>点击直达（零弹窗）</strong>：<code>preview</code> 开启时内部给 ElImage 绑定 <code>preview-src-list</code>（= <code>[previewSrc ?? src]</code>）+ <code>preview-teleported</code>——点击图片即打开 <strong>el-image-viewer 全屏放大</strong>（缩放/旋转/切换/ESC/遮罩关闭全原生）——<strong>一层到位</strong></li><li><strong>命令式与点击两入口各司其职</strong>：点击 → ElImage 原生预览（本组件）；命令式 → <code>ModalImagePreview</code>（ElImageViewer 薄适配，全局遥控器 evoke）——触发组件 [MUST NOT] 再走弹窗（两层预览嵌套已废弃）</li></ul><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ImagePreviewTrigger</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/thumb.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p><strong>要点</strong>：</p><ul><li><code>src</code> 必传（缩略图路径）；零配置即带原生懒加载 + 占位兜底 + <strong>点击放大</strong></li><li>大图与原图分离：<code>previewSrc</code> 传原图（点击放大打开的大图），<strong>缺省降级为 <code>src</code></strong>（缩略图即原图时零配置）</li><li>点击后：el-image-viewer 全屏放大（ep 原生）——无环境依赖、无决策链、无弹窗</li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong>默认即够用：缩略图 + 懒加载 + 点击放大</strong>——绝大多数场景只传 <code>src</code>。</li><li><code>previewSrc</code>：仅当缩略图/原图分离（如压缩图列表）时传；缺省 = <code>src</code>。</li><li><code>#placeholder</code> / <code>#error</code> 插槽：仅当需要自定义加载中/失败兜底图（小图 / base64）时传；缺省 EP 默认观感（灰底加载中 + 失败图标）。</li><li><code>lazy={false}</code>：仅当图片必须立即加载（首屏无滚动场景）时关。</li><li><code>preview={false}</code>：关闭点击放大（纯展示缩略图）——仍保留懒加载 + 占位兜底。</li><li><strong>点击不冒泡（仅 <code>preview</code> 开启时）</strong>：打开放大的同时 <code>stopPropagation</code>——缩略图常嵌在表格行 / 卡片里，点图看大图 [MUST NOT] 连带触发行点击 / 卡片跳转。<code>preview={false}</code>（纯展示）<strong>不拦</strong>，事件照常上抛给外层（此时组件不做任何事，吞事件反而会让外层行点击失效）。</li><li><strong>完整能力演示</strong>：<code>apps/reference/src/pages/modal/preview/showcase/</code>——能力展示，非推荐默认。</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props-内联-defineprops-无-types-ts" tabindex="-1">Props（内联 defineProps，无 types.ts） <a class="header-anchor" href="#props-内联-defineprops-无-types-ts" aria-label="Permalink to &quot;Props（内联 defineProps，无 types.ts）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>src</code></td><td><code>string</code>（必传）</td><td>—</td><td>缩略图路径（ElImage.src）</td></tr><tr><td><code>previewSrc</code></td><td><code>string</code></td><td>—</td><td>原图路径（点击放大打开的大图）；<strong>缺省降级为 <code>src</code></strong></td></tr><tr><td><code>lazy</code></td><td><code>boolean</code></td><td><code>true</code></td><td>图片懒加载（ElImage.lazy，原生 loading 优先）</td></tr><tr><td><code>preview</code></td><td><code>boolean</code></td><td><code>true</code></td><td>是否可点击放大（内部绑定 <code>preview-src-list</code>；false = 纯展示缩略图）</td></tr></tbody></table><blockquote><p><strong>ElImage / img 原生属性全量透传</strong>：<code>$attrs</code> 直达自身 ElImage——<code>alt</code> / <code>fit</code> / <code>loading</code> / <code>draggable</code> / <code>scroll-container</code> 等原生属性与 EP 图片属性均可用。 ⚠ <strong><code>width</code> / <code>height</code> 无效</strong>：EP 2.13 的 ElImage 未声明 width/height props，透传会落根 div 的 HTML attribute（对 div 无渲染效果）。尺寸控制请用外层 CSS / <code>style</code>（配合 <code>fit=&quot;cover&quot;</code> 居中裁切）。</p></blockquote><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><p>无</p><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td><code>#placeholder</code></td><td>无</td><td>加载中占位（透传 ElImage；缺省 EP 灰底观感）</td></tr><tr><td><code>#error</code></td><td>无</td><td>加载失败兜底图（透传 ElImage；缺省 EP 失败图标）——<strong>插槽非属性</strong>，传兜底图走插槽内放 <code>&lt;img&gt;</code></td></tr></tbody></table><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无</p><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong>[MUST NOT] 点击走弹窗</strong>：图片预览终点 = el-image-viewer（ElImage 原生）——弹窗 → 弹窗内再点放大 = 两层嵌套（脱裤子放屁，已废弃）；命令式开图走 <code>ModalImagePreview</code>，与点击路径分离</li><li><strong><code>previewSrc</code> 才是预览路径</strong>：<code>src</code> 是展示路径——缩略图/原图分离时别把大图塞 <code>src</code>（懒加载白拉全尺寸图）</li><li><strong><code>#error</code> 是插槽不是属性</strong>：传字符串路径是 EP 常见误区（加载失败显示空白）——兜底图放插槽内 <code>&lt;img :src&gt;</code>（或 base64）</li><li><strong><code>preview=false</code> 只关放大</strong>：仍渲染缩略图 + 懒加载 + 占位兜底——「图片展示」能力不随「预览」关掉</li><li><strong>[MUST NOT] 外层再包 <code>@click.stop</code> 兜底</strong>：<code>preview</code> 开启时组件内部已阻止冒泡；外层再包会把<strong>纯展示态</strong>（<code>preview=false</code>）的点击一并吞掉，外层行点击 / 卡片跳转随之失效</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>命令式弹窗端：<code>ModalImagePreview</code>（ElImageViewer 薄适配 + 弹窗配置化契约；全局遥控器 <code>evoke(APP_GLOBAL_IMAGE_PREVIEW_KEY, { src })</code>）</li><li>对等组件：<code>VideoPreviewTrigger</code>（视频触发端；封面/占位 + 播放图标两形态统一，仍需弹窗——视频无 el 原生预览）</li><li>命令式弹窗体系：<code>ModalShelf</code>（架子 + level 层级）+ <code>ModalPorter</code>（modalList 注册表）+ 全局遥控器（<code>globalModalRemote</code>）</li><li>范式页：<code>apps/reference/src/pages/modal/preview/showcase/</code></li></ul>',25)])])}const m=o(a,[["render",c]]);export{h as __pageData,m as default};
